import{_ as t}from"./chunks/weihnachtssteuerung-card.qFlEh_04.js";import{_ as a,o as r,c as s,a3 as n}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse('{"title":"Festtags-Card-Editor","description":"Christmas scheduling with five controls, observance pictures, GIF decoration and snowfall.","frontmatter":{"title":"Festtags-Card-Editor","description":"Christmas scheduling with five controls, observance pictures, GIF decoration and snowfall."},"headers":[],"relativePath":"en/projects/festtags-card-editor/index.md","filePath":"en/projects/festtags-card-editor/index.md","lastUpdated":1795858977000}'),i={name:"en/projects/festtags-card-editor/index.md"};function o(d,e,l,c,h,u){return r(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="festtags-card-editor" tabindex="-1">Festtags-Card-Editor <a class="header-anchor" href="#festtags-card-editor" aria-label="Permalink to &quot;Festtags-Card-Editor&quot;">​</a></h1><p><strong>Version 0.1.12</strong> · Editor DE/EN · Documentation DE/EN/FR.</p><p><a href="/projects/festtags-card-editor/">Deutsch</a> · <a href="/fr/projects/festtags-card-editor/">Français</a></p><p><img src="'+t+`" alt="Christmas control with a custom background, snowfall and two lighting controls"></p><p>Example from a configured dashboard. The background artwork is supplied by the user and is not included in the app package. The screenshot cannot show the falling snow in motion.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li>Select region/country: 47 countries and custom dates, western/Julian traditions.</li><li>Up to five targets (<code>light</code>, <code>switch</code>, <code>input_boolean</code>), each with individual on/off times.</li><li>Daily within a range or on selected observances; annual Advent dates and year rollover are automatic.</li><li>Default season: first Advent Sunday through January 10 inclusive. Pause states persist across restarts.</li><li>Current/next observance and next-switch sensors, plus a dashboard card.</li><li>Optional live status icon: <code>mdi:lightbulb</code> for on, <code>mdi:lightbulb-outline</code> for off.</li></ul><p>Country presets suggest observances and customs, not a complete statutory holiday calendar. First/Second Christmas Day, Saint Stephen&#39;s Day, Sinterklaas, Pakjesavond, Three Kings and Epiphany are separate entries. Some share a date.</p><h2 id="installation-and-updates" tabindex="-1">Installation and updates <a class="header-anchor" href="#installation-and-updates" aria-label="Permalink to &quot;Installation and updates&quot;">​</a></h2><ol><li>Create a full HA backup and add/refresh the <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons" target="_blank" rel="noreferrer">UGSo app repository</a>.</li><li>Install/update and start <strong>Festtags-Card-Editor</strong>. Architectures: aarch64 and amd64.</li><li><strong>Restart Home Assistant itself</strong>, not just the editor app, to load the updated integration.</li><li>Open the editor. On first installation select <strong>Set up integration</strong>. Configure country, targets and times, then save.</li><li>Select <strong>Register card resource</strong> and fully reload the dashboard.</li></ol><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom:weihnachtssteuerung-card</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Christmas control</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Existing settings and user pictures are preserved. Scheduling runs inside HA Core even when the editor app is stopped. Administrators access the editor through Ingress. Search targets by name, ID, area or device.</p><h2 id="own-pictures-and-backgrounds" tabindex="-1">Own pictures and backgrounds <a class="header-anchor" href="#own-pictures-and-backgrounds" aria-label="Permalink to &quot;Own pictures and backgrounds&quot;">​</a></h2><p>No artwork is bundled. Use your own files with appropriate usage rights.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Purpose</th><th>HA directory</th><th>URL path</th></tr></thead><tbody><tr><td>Pictures per country/observance</td><td><code>/config/www/weihnachtssteuerung/bilder</code></td><td><code>/local/weihnachtssteuerung/bilder</code></td></tr><tr><td>Backgrounds and decorations</td><td><code>/config/www/weihnachtssteuerung/background</code></td><td><code>/local/weihnachtssteuerung/background</code></td></tr></tbody></table></div><p>Upload PNG, JPG, WebP or GIF (maximum 5 MiB/16 megapixels); animations remain unchanged. Existing SVG files can be assigned, but not uploaded. Duplicate filenames are suffixed rather than overwritten. <strong>Unassign</strong>/<strong>No file</strong> only removes the mapping.</p><p>Observance pictures appear 110 px high in the card, preserving aspect ratio; editor previews are 90 × 90 px. Several pictures can appear together. Background and decoration have independent transparency, size and X/Y position. Transparency 0% = visible, 100% = invisible; X/Y 0/0 = top left, 100/100 = bottom right. Darkening improves readability. Text and buttons remain usable above the effects.</p><h2 id="snowfall" tabindex="-1">Snowfall <a class="header-anchor" href="#snowfall" aria-label="Permalink to &quot;Snowfall&quot;">​</a></h2><ul><li>Select <strong>Snowfall</strong> or <strong>Image + snowfall</strong>. A separate GIF decoration can also be enabled.</li><li>6–40 particles; actual circular diameter 1–20 CSS pixels, default 4 px.</li><li><strong>Animate snowfall anyway</strong> explicitly overrides reduced motion for this card only. Off by default.</li><li>Animation still pauses offscreen or when the page is hidden.</li><li>Save settings; after a card-file update register the resource and reload the dashboard.</li></ul><h2 id="confirmed-chrome-test-on-november-25-2026" tabindex="-1">Confirmed Chrome test on November 25, 2026 <a class="header-anchor" href="#confirmed-chrome-test-on-november-25-2026" aria-label="Permalink to &quot;Confirmed Chrome test on November 25, 2026&quot;">​</a></h2><p>On one HA installation with card <strong>0.1.12</strong>, a loaded GIF and <strong>30 simultaneously animated snowflakes</strong> were confirmed. Particle position changed between two observations; animation <code>snow-fall</code>, state <code>running</code>. No settings were changed during this combination test. This is not a performance guarantee for all tablets.</p><p><strong>Firefox animates but Chrome does not:</strong> In the observed case Chrome still loaded the <strong>0.1.8</strong> resource. Reloading alone did not replace the old resource reference. Use <strong>Register card resource</strong> in the current editor, then fully reload the dashboard. With reduced motion enabled, also save the explicit override. The visible card resumes once the current file and the override are effective.</p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/festtags-card-editor-v0.1.12" target="_blank" rel="noreferrer">Release and ZIP downloads</a></li><li><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/festtags_card_editor" target="_blank" rel="noreferrer">Source and detailed guide</a></li><li><a href="/en/projects-mqtt/">UGSo HA Apps</a></li></ul>`,24)])])}const m=a(i,[["render",o]]);export{f as __pageData,m as default};
